target.css:
:root {
  --ink: #29211f;
  --muted: #766963;
  --paper: #fffaf4;
  --panel: #f5ebe0;
  --line: #ddcabc;
  --espresso: #56362c;
  --crema: #d98245;
  --mint: #367b67;
  --coral: #c95c47;
}

.station {
  box-sizing: border-box;
  width: 500px;
  height: 278px;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.station__head {
  flex: 0 0 42px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--line);
}

.station__title {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.eyebrow {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.live-pill {
  margin: 0;
  padding: 5px 8px;
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--coral);
  background: var(--panel);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.live-pill__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--coral);
}

.station__body {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: 1.12fr 0.88fr;
  gap: 10px;
}

.shot-card,
.recipe-card {
  box-sizing: border-box;
  min-width: 0;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
}

.shot-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  background: var(--espresso);
  color: var(--paper);
  border-color: var(--espresso);
}

.shot-card__caption {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.shot-card__caption strong {
  color: var(--crema);
  font-size: 20px;
  letter-spacing: -0.04em;
}

.gauge {
  height: 12px;
  overflow: hidden;
  background: var(--paper);
  border-radius: 999px;
}

.gauge__fill {
  display: block;
  width: 72%;
  height: 100%;
  background: var(--crema);
  border-radius: 999px;
}

.gauge__scale {
  display: flex;
  justify-content: space-between;
  color: var(--line);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.07em;
}

.shot-note {
  margin: 0;
  color: var(--panel);
  font-size: 11px;
  line-height: 1.2;
}

.recipe-card {
  display: flex;
  flex-direction: column;
  background: var(--panel);
}

.recipe-card__head {
  display: flex;
  justify-content: space-between;
  padding-bottom: 7px;
  color: var(--muted);
  border-bottom: 1px solid var(--line);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.recipe-card__head strong {
  color: var(--mint);
}

.recipe-list {
  margin: 6px 0;
  padding: 0;
  display: grid;
  gap: 3px;
  list-style: none;
}

.recipe-list li {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  line-height: 1.25;
}

.recipe-list li span {
  color: var(--muted);
}

.recipe-tip {
  margin: auto 0 0;
  padding-top: 6px;
  color: var(--mint);
  border-top: 1px solid var(--line);
  font-size: 10px;
  font-weight: 700;
}

.station__foot {
  flex: 0 0 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.station__foot p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
}

.coffee-mark {
  color: var(--crema);
  font-size: 12px;
}

.actions {
  display: flex;
  gap: 6px;
}

button {
  padding: 6px 9px;
  border-radius: 7px;
  font: inherit;
  font-size: 11px;
  font-weight: 700;
}

.ghost-button {
  color: var(--espresso);
  background: var(--paper);
  border: 1px solid var(--line);
}

.primary-button {
  color: var(--paper);
  background: var(--mint);
  border: 1px solid var(--mint);
}

